async function main(){if(figma.fileKey&&figma.fileKey!=="zJ6BhvNM0UrHURsWOh3PmK")throw new Error("Откройте созданный файл Тройки, указанный в FIGMA.md");let count=0;for(const payload of DATA){const page=await figma.getNodeByIdAsync(payload.PAGE_ID);if(!page||page.type!=="PAGE")throw new Error("Не найдена страница Тройки");payload.SCENES=payload.SCENES.filter(s=>!page.children.some(n=>n.name===(s.theme==="dark"?"Тёмная / ":"Светлая / ")+s.name));if(!payload.SCENES.length)continue;const result=await importPage(payload);if(result.geometryErrors.length)throw new Error("Проверьте размеры импортированных блоков");count+=result.frames.length;figma.currentPage.selection=await Promise.all(result.frames.map(f=>figma.getNodeByIdAsync(f.id)));figma.viewport.scrollAndZoomIntoView(figma.currentPage.selection);}figma.closePlugin("Добавлено макетов: "+count)}
